SELECT jsonb_build_object('contas',(SELECT jsonb_agg(to_jsonb(c)) FROM tb_contas c WHERE tipo_titular='PJ'), 'profile_exists',to_regclass('public.tb_conta_perfis_publicos')::text,'constraints',(SELECT jsonb_agg(pg_get_constraintdef(oid)) FROM pg_constraint WHERE conrelid='tb_contas'::regclass),'triggers',(SELECT jsonb_agg(tgname) FROM pg_trigger WHERE tgrelid='tb_contas'::regclass AND NOT tgisinternal))::text payload
